// Oracle test for the CUDA->HIP compatibility header: FP8 E4M3FN and BF16 conversions must match
// the bit-exact reference tables in fp8_bf16_reference.inc (generated by gen_fp8_bf16_reference.py
// from the OCP OFP8 / IEEE-754 specifications, independent of any repository code).
//
// Written BEFORE the header exists (task R97-02); it is expected not to compile until then.
//
// CONTRACT assumed of the header (rename here if the author picks another name/API):
//   #include "core/cuda_compat.h"   -- on a CUDA build it must be a transparent pass-through, on HIP it
//                                      must provide, with the CUDA spelling used by src/:
//   * runtime:  cudaGetDeviceCount cudaMalloc cudaMemcpy(+cudaMemcpyHostToDevice/DeviceToHost)
//               cudaDeviceSynchronize cudaGetLastError cudaGetErrorString cudaFree cudaSuccess
//   * types:    __nv_bfloat16 __nv_bfloat162 __half __half2 __nv_fp8_e4m3 (public member __x,
//               explicit float conversion, static_cast<__half>) __nv_fp8x2_e4m3 (member __x, low byte =
//               .x lane, static_cast<float2> / static_cast<__half2>); float2 + make_float2;
//               sizeof 2 / 4 / 2 / 4 / 1 / 2 (src/ reinterpret_casts these)
//   * bf16:     __float2bfloat16_rn __float2bfloat16 __bfloat162float __bfloat1622float2
//               __floats2bfloat162_rn __halves2bfloat162 __low2bfloat16 __high2bfloat16
//               __bfloat16_as_ushort __ushort_as_bfloat16, __nv_bfloat16_raw / __nv_bfloat162_raw
//               (members x / y) with implicit conversion from the bf16 types
//   * half:     __half2float __low2half __high2half
//   * fp8:      __nv_cvt_float_to_fp8(float, __NV_SATFINITE, __NV_E4M3) -> 8-bit storage,
//               __nv_cvt_float2_to_fp8x2(float2, __NV_SATFINITE, __NV_E4M3) -> 16-bit storage
//               (x lane in the low byte)
//   All of the above callable from host and device code (the same probes run in both).
//
// Why .cu: the production path is device code, so each probe also runs in a kernel. Without a
// device the host half still runs and the test exits 77 (ctest SKIP_RETURN_CODE); --require-device
// turns "no device" into a failure.
#include "core/cuda_compat.h"

#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <string>
#include <vector>

#define HD __host__ __device__

static_assert(sizeof(__nv_bfloat16) == 2 && sizeof(__nv_bfloat162) == 4, "bf16 layout");
static_assert(sizeof(__nv_fp8_e4m3) == 1 && sizeof(__nv_fp8x2_e4m3) == 2, "fp8 layout");

namespace {

// ---- reference tables (the only source of expected values) --------------------------------
struct Fp8Decode { std::uint8_t code; std::uint32_t bits; bool nan; };
struct Fp8Encode { std::uint32_t in; std::uint8_t code; bool nan; };
struct Bf16Encode { std::uint32_t in; std::uint16_t code; bool nan; };
struct Bf16Decode { std::uint16_t code; std::uint32_t bits; bool nan; };

const Fp8Decode kFp8Decode[] = {
#define NINFER_REF_FP8_DECODE
#include "fp8_bf16_reference.inc"
#undef NINFER_REF_FP8_DECODE
};
const Fp8Encode kFp8Encode[] = {
#define NINFER_REF_FP8_ENCODE_SATFINITE
#include "fp8_bf16_reference.inc"
#undef NINFER_REF_FP8_ENCODE_SATFINITE
};
const Bf16Encode kBf16Encode[] = {
#define NINFER_REF_BF16_ENCODE_RNE
#include "fp8_bf16_reference.inc"
#undef NINFER_REF_BF16_ENCODE_RNE
};
const Bf16Decode kBf16Decode[] = {
#define NINFER_REF_BF16_DECODE
#include "fp8_bf16_reference.inc"
#undef NINFER_REF_BF16_DECODE
};

// ---- helpers ---------------------------------------------------------------------------------
HD inline std::uint32_t f2u(float x) { std::uint32_t u; std::memcpy(&u, &x, 4); return u; }
HD inline float u2f(std::uint32_t u) { float x; std::memcpy(&x, &u, 4); return x; }
inline bool f32_is_nan(std::uint32_t b) { return (b & 0x7FFFFFFFu) > 0x7F800000u; }
inline bool same_f32(std::uint32_t got, std::uint32_t want, bool nan) {
    return nan ? f32_is_nan(got) : got == want;
}

// ---- probes: identical source runs on the host and in a kernel -------------------------------
// Each probe sees case i and case i+1 so the two-lane (x2) APIs test both lanes independently.

struct Fp8DecodeProbe {            // input: fp8 code
    using In = std::uint8_t;
    struct Out { std::uint32_t scalar, lo, hi, half_scalar, half_lo, half_hi; };
    HD Out operator()(In a, In b) const {
        Out o;
        __nv_fp8_e4m3 c;
        c.__x = a;
        o.scalar      = f2u(static_cast<float>(c));
        o.half_scalar = f2u(__half2float(static_cast<__half>(c)));
        __nv_fp8x2_e4m3 p;
        p.__x = static_cast<std::uint16_t>(a | (static_cast<std::uint16_t>(b) << 8));
        const float2 f = static_cast<float2>(p);
        o.lo = f2u(f.x);
        o.hi = f2u(f.y);
        const __half2 h = static_cast<__half2>(p);
        o.half_lo = f2u(__half2float(__low2half(h)));
        o.half_hi = f2u(__half2float(__high2half(h)));
        return o;
    }
};

struct Fp8EncodeProbe {            // input: float bits
    using In = std::uint32_t;
    struct Out { std::uint8_t scalar; std::uint16_t pair; };
    HD Out operator()(In a, In b) const {
        Out o;
        o.scalar = __nv_cvt_float_to_fp8(u2f(a), __NV_SATFINITE, __NV_E4M3);
        o.pair   = __nv_cvt_float2_to_fp8x2(make_float2(u2f(a), u2f(b)), __NV_SATFINITE, __NV_E4M3);
        return o;
    }
};

struct Bf16EncodeProbe {           // input: float bits
    using In = std::uint32_t;
    struct Out { std::uint16_t rn, dflt, raw, pair_lo, pair_hi; };
    HD Out operator()(In a, In b) const {
        Out o;
        const float x = u2f(a), y = u2f(b);
        o.rn   = __bfloat16_as_ushort(__float2bfloat16_rn(x));
        o.dflt = __bfloat16_as_ushort(__float2bfloat16(x));
        const __nv_bfloat16_raw r = __float2bfloat16_rn(x);
        o.raw = r.x;
        const __nv_bfloat162_raw pr = __floats2bfloat162_rn(x, y);
        o.pair_lo = pr.x;
        o.pair_hi = pr.y;
        return o;
    }
};

struct Bf16DecodeProbe {           // input: bf16 bits
    using In = std::uint16_t;
    struct Out { std::uint32_t scalar, lo, hi; std::uint16_t low_bits, high_bits; };
    HD Out operator()(In a, In b) const {
        Out o;
        const __nv_bfloat16 x = __ushort_as_bfloat16(a), y = __ushort_as_bfloat16(b);
        o.scalar = f2u(__bfloat162float(x));
        const __nv_bfloat162 p = __halves2bfloat162(x, y);
        const float2 f = __bfloat1622float2(p);
        o.lo = f2u(f.x);
        o.hi = f2u(f.y);
        o.low_bits  = __bfloat16_as_ushort(__low2bfloat16(p));
        o.high_bits = __bfloat16_as_ushort(__high2bfloat16(p));
        return o;
    }
};

template <class P>
__global__ void probe_kernel(const typename P::In* in, typename P::Out* out, int n) {
    const int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) out[i] = P{}(in[i], in[(i + 1) % n]);
}

// ---- driver --------------------------------------------------------------------------------
struct State {
    bool device = false;
    int failures = 0;
    int shown = 0;
    void fail(const char* section, const char* where, std::size_t i, const char* what,
              std::uint64_t got, std::uint64_t want) {
        ++failures;
        if (shown++ < 40)
            std::printf("  MISMATCH %s [%s] case %zu %s: got 0x%llX want 0x%llX\n", section, where, i,
                        what, (unsigned long long)got, (unsigned long long)want);
    }
};

bool cuda_ok(cudaError_t e, const char* what) {
    if (e == cudaSuccess) return true;
    std::printf("  CUDA error in %s: %s\n", what, cudaGetErrorString(e));
    return false;
}

// verify(where, outputs) compares every output with the reference, reporting through State.
template <class P, class Verify>
void run_section(State& st, const char* section, const std::vector<typename P::In>& in, Verify verify) {
    using In = typename P::In;
    using Out = typename P::Out;
    const int n = static_cast<int>(in.size());
    const int before = st.failures;

    std::vector<Out> host(n);
    for (int i = 0; i < n; ++i) host[i] = P{}(in[i], in[(i + 1) % n]);
    verify("host", host);

    if (st.device) {
        In* d_in = nullptr;
        Out* d_out = nullptr;
        std::vector<Out> dev(n);
        bool ok = cuda_ok(cudaMalloc(&d_in, n * sizeof(In)), "cudaMalloc in") &&
                  cuda_ok(cudaMalloc(&d_out, n * sizeof(Out)), "cudaMalloc out") &&
                  cuda_ok(cudaMemcpy(d_in, in.data(), n * sizeof(In), cudaMemcpyHostToDevice), "H2D");
        if (ok) {
            probe_kernel<P><<<(n + 255) / 256, 256>>>(d_in, d_out, n);
            ok = cuda_ok(cudaGetLastError(), "launch") && cuda_ok(cudaDeviceSynchronize(), "sync") &&
                 cuda_ok(cudaMemcpy(dev.data(), d_out, n * sizeof(Out), cudaMemcpyDeviceToHost), "D2H");
        }
        cudaFree(d_in);
        cudaFree(d_out);
        if (ok) verify("device", dev); else ++st.failures;
    }
    std::printf("[%s] %-34s %zu cases (host%s)\n", st.failures == before ? "PASS" : "FAIL", section,
                in.size(), st.device ? " + device" : " only");
}

}  // namespace

int main(int argc, char** argv) {
    bool require_device = false;
    for (int i = 1; i < argc; ++i)
        if (std::string(argv[i]) == "--require-device") require_device = true;

    State st;
    int devices = 0;
    st.device = cudaGetDeviceCount(&devices) == cudaSuccess && devices > 0;
    if (!st.device) {
        (void)cudaGetLastError();
        std::printf("no device: running the host half only%s\n", require_device ? " (FAIL: --require-device)" : "");
        if (require_device) ++st.failures;
    }

    {   // FP8 e4m3fn -> float / half, all 256 codes; lane 2 sees the next code
        std::vector<std::uint8_t> in;
        for (const auto& c : kFp8Decode) in.push_back(c.code);
        const std::size_t n = in.size();
        run_section<Fp8DecodeProbe>(st, "fp8 e4m3fn decode (256 codes)", in,
            [&](const char* w, const auto& out) {
                for (std::size_t i = 0; i < n; ++i) {
                    const auto &e = kFp8Decode[i], &e2 = kFp8Decode[(i + 1) % n];
                    const auto& o = out[i];
                    auto chk = [&](const char* what, std::uint32_t got, const Fp8Decode& x) {
                        if (!same_f32(got, x.bits, x.nan)) st.fail("fp8_decode", w, i, what, got, x.bits);
                    };
                    chk("float(__nv_fp8_e4m3)", o.scalar, e);
                    chk("half(__nv_fp8_e4m3)", o.half_scalar, e);
                    chk("float2(x2).x", o.lo, e);
                    chk("float2(x2).y", o.hi, e2);
                    chk("half2(x2).x", o.half_lo, e);
                    chk("half2(x2).y", o.half_hi, e2);
                }
            });
    }
    {   // float -> FP8 e4m3fn, RNE + __NV_SATFINITE
        std::vector<std::uint32_t> in;
        for (const auto& c : kFp8Encode) in.push_back(c.in);
        const std::size_t n = in.size();
        run_section<Fp8EncodeProbe>(st, "float->fp8 e4m3fn satfinite", in,
            [&](const char* w, const auto& out) {
                for (std::size_t i = 0; i < n; ++i) {
                    const auto &e = kFp8Encode[i], &e2 = kFp8Encode[(i + 1) % n];
                    const auto& o = out[i];
                    auto chk = [&](const char* what, unsigned got, const Fp8Encode& x) {
                        const bool ok = x.nan ? (got & 0x7F) == 0x7F : got == x.code;
                        if (!ok) st.fail("fp8_encode", w, i, what, got, x.code);
                    };
                    chk("__nv_cvt_float_to_fp8", o.scalar, e);
                    chk("__nv_cvt_float2_to_fp8x2.x", o.pair & 0xFF, e);
                    chk("__nv_cvt_float2_to_fp8x2.y", o.pair >> 8, e2);
                }
            });
    }
    {   // float -> BF16, RNE (CUDA's __float2bfloat16 is RN as well)
        std::vector<std::uint32_t> in;
        for (const auto& c : kBf16Encode) in.push_back(c.in);
        const std::size_t n = in.size();
        run_section<Bf16EncodeProbe>(st, "float->bf16 round-to-nearest-even", in,
            [&](const char* w, const auto& out) {
                for (std::size_t i = 0; i < n; ++i) {
                    const auto &e = kBf16Encode[i], &e2 = kBf16Encode[(i + 1) % n];
                    const auto& o = out[i];
                    auto chk = [&](const char* what, unsigned got, const Bf16Encode& x) {
                        const bool ok = x.nan ? ((got & 0x7F80) == 0x7F80 && (got & 0x7F) != 0)
                                              : got == x.code;
                        if (!ok) st.fail("bf16_encode", w, i, what, got, x.code);
                    };
                    chk("__float2bfloat16_rn", o.rn, e);
                    chk("__float2bfloat16", o.dflt, e);
                    chk("__nv_bfloat16_raw", o.raw, e);
                    chk("__floats2bfloat162_rn.x", o.pair_lo, e);
                    chk("__floats2bfloat162_rn.y", o.pair_hi, e2);
                }
            });
    }
    {   // BF16 -> float is exact (sample covers every exponent, both signs, subnormals, inf, NaN)
        std::vector<std::uint16_t> in;
        for (const auto& c : kBf16Decode) in.push_back(c.code);
        const std::size_t n = in.size();
        run_section<Bf16DecodeProbe>(st, "bf16->float exact", in,
            [&](const char* w, const auto& out) {
                for (std::size_t i = 0; i < n; ++i) {
                    const auto &e = kBf16Decode[i], &e2 = kBf16Decode[(i + 1) % n];
                    const auto& o = out[i];
                    auto chk = [&](const char* what, std::uint32_t got, const Bf16Decode& x) {
                        if (!same_f32(got, x.bits, x.nan)) st.fail("bf16_decode", w, i, what, got, x.bits);
                    };
                    chk("__bfloat162float", o.scalar, e);
                    chk("__bfloat1622float2.x", o.lo, e);
                    chk("__bfloat1622float2.y", o.hi, e2);
                    if (o.low_bits != e.code) st.fail("bf16_decode", w, i, "__low2bfloat16", o.low_bits, e.code);
                    if (o.high_bits != e2.code) st.fail("bf16_decode", w, i, "__high2bfloat16", o.high_bits, e2.code);
                }
            });
    }

    if (st.failures) {
        std::printf("FAILED: %d mismatches\n", st.failures);
        return 1;
    }
    if (!st.device) {
        std::printf("SKIPPED device half (host half passed)\n");
        return 77;
    }
    std::printf("OK\n");
    return 0;
}
